#[cfg(test)]
mod tests {
    use rigorix_engine::effect_commitment::application::{
        EffectCommitmentBackendConfig, EffectCommitmentConfig, ProviderReceiptConfig,
    };

    #[test]
    fn test_effectcommitmentconfig_is_defined() {
        let in_memory = EffectCommitmentConfig::new(EffectCommitmentBackendConfig::InMemory, None);
        assert!(!in_memory.can_prove_commitment());
        assert!(matches!(
            in_memory.backend,
            EffectCommitmentBackendConfig::InMemory
        ));

        // Without a receipt reader the honest claim ceiling is "not settled".
        let with_reader = EffectCommitmentConfig::new(
            EffectCommitmentBackendConfig::Http {
                base_url: "https://commitment.example".to_string(),
                timeout_ms: 5_000,
                max_response_body_bytes: 65_536,
                auth_token: None,
            },
            Some(ProviderReceiptConfig::new(
                "https://payments.example",
                "stripe",
                5_000,
                65_536,
                None,
            )),
        );
        assert!(with_reader.can_prove_commitment());
        assert_eq!(
            with_reader
                .receipt_reader
                .as_ref()
                .map(|r| r.provider_id.as_str()),
            Some("stripe")
        );
    }

    #[test]
    fn test_effectcommitmentconfig_interacts_with_none() {
        // The opt-in rule: no declaration means no adapter and the previous
        // code path. A missing file is `Ok(None)`, not an error.
        let scratch = std::env::temp_dir().join(format!(
            "rigorix-effect-config-{}-{}",
            std::process::id(),
            uuid::Uuid::new_v4()
        ));
        std::fs::create_dir_all(&scratch).unwrap();

        let runtime = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .unwrap();
        let setup = runtime.block_on(
            rigorix_engine::effect_commitment::application::EffectCommitmentSetup::from_env(
                &scratch,
            ),
        );
        assert!(matches!(setup, Ok(None)));

        // A present declaration is fail-closed while the parser/composition path
        // is still stubbed: it must never silently downgrade to "not armed".
        std::fs::create_dir_all(scratch.join(".rigorix")).unwrap();
        std::fs::write(
            scratch.join(".rigorix/effect-commitment.toml"),
            "[backend]\nkind = \"in_memory\"\n",
        )
        .unwrap();
        let setup = runtime.block_on(
            rigorix_engine::effect_commitment::application::EffectCommitmentSetup::from_env(
                &scratch,
            ),
        );
        assert!(setup.is_err());
    }
}
